config.command:
set -eu
: > raw_subdomains.txt
if command -v subfinder >/dev/null 2>&1; then
  subfinder -d "{domain}" -silent >> raw_subdomains.txt || true
else
  echo 'subfinder not installed; continuing with web sources' >&2
fi
TARGET_DOMAIN="{domain}" node <<'JS' >> raw_subdomains.txt
const domain = process.env.TARGET_DOMAIN;
const clean = (value) => String(value || '').replace(/^\*\./, '').toLowerCase();
async function crtsh() {
  const url = `https://crt.sh/?q=%25.${domain}&output=json`;
  const response = await fetch(url, { signal: AbortSignal.timeout(20000) });
  if (!response.ok) return;
  const rows = await response.json().catch(() => []);
  for (const row of rows) {
    for (const name of String(row.name_value || '').split(/\n+/)) {
      const host = clean(name.trim());
      if (host.endsWith(`.${domain}`) || host === domain) console.log(host);
    }
  }
}
async function certspotter() {
  const url = `https://api.certspotter.com/v1/issuances?domain=${encodeURIComponent(domain)}&include_subdomains=true&expand=dns_names`;
  const response = await fetch(url, { signal: AbortSignal.timeout(20000) }).catch(() => null);
  if (!response || !response.ok) return;
  const rows = await response.json().catch(() => []);
  for (const row of rows) {
    for (const name of row.dns_names || []) {
      const host = clean(name);
      if (host.endsWith(`.${domain}`) || host === domain) console.log(host);
    }
  }
}
await Promise.allSettled([crtsh(), certspotter()]);
JS
sort -u raw_subdomains.txt
